    Question(id: 't2_l1_q1', levelId: 't2_l1', type: QuestionType.singleChoice, question: 'Vật nào dưới đây rất nóng và có thể làm bỏng?', options: ['Bàn chải', 'Bàn là (bàn ủi)', 'Gối'], correctAnswers: [1], hint: 'Vật này dùng để làm phẳng quần áo.', explanation: 'Bàn là rất nóng, tuyệt đối không được chạm vào.'),
    Question(id: 't2_l1_q2', levelId: 't2_l1', type: QuestionType.multipleChoice, question: 'Những vật sắc nhọn cần tránh xa?', options: ['Dao', 'Thìa', 'Kéo', 'Cốc nhựa'], correctAnswers: [0, 2], hint: 'Những vật dùng để cắt thường rất nguy hiểm.', explanation: 'Dao và kéo có thể làm đứt tay nếu không cẩn thận.'),
    Question(id: 't2_l1_q3', levelId: 't2_l1', type: QuestionType.dialogue, question: 'Con làm thế nào?', options: ['Tự bắc ghế trèo lên', 'Nhờ bố mẹ lấy hộ'], correctAnswers: [1], hint: 'Trèo cao rất dễ bị ngã.', explanation: 'Nên nhờ người lớn để tránh bị ngã.', characterDialogue: 'Con muốn lấy gấu bông trên tủ cao.'),
    Question(id: 't2_l2_q1', levelId: 't2_l2', type: QuestionType.singleChoice, question: 'Tay đang ướt có nên chạm vào ổ cắm điện không?', options: ['Có', 'Không'], correctAnswers: [1], hint: 'Nước truyền điện rất mạnh.', explanation: 'Tay ướt chạm vào điện sẽ bị giật rất nguy hiểm.'),
    Question(id: 't2_l2_q2', levelId: 't2_l2', type: QuestionType.multipleChoice, question: 'Đâu là hóa chất độc hại trong nhà?', options: ['Sữa', 'Nước tẩy bồn cầu', 'Kẹo', 'Nước rửa bát'], correctAnswers: [1, 3], hint: 'Những chất dùng để lau chùi thường có hóa chất.', explanation: 'Chai lọ tẩy rửa chứa hóa chất độc hại, không được nếm.'),
    Question(id: 't2_l2_q3', levelId: 't2_l2', type: QuestionType.dialogue, question: 'Con sẽ làm gì?', options: ['Mặc kệ em', 'Chạy ra cản em lại và gọi người lớn'], correctAnswers: [1], hint: 'Điện giật rất nguy hiểm cho em bé.', explanation: 'Phải cản em lại ngay và báo cho người lớn.', characterDialogue: 'Em bé đang định thò ngón tay vào ổ điện.'),
    Question(id: 't2_l3_q1', levelId: 't2_l3', type: QuestionType.singleChoice, question: 'Khi ngửi thấy mùi khét hoặc khói, con nên làm gì?', options: ['Đi ngủ', 'Báo ngay cho người lớn', 'Mở TV xem'], correctAnswers: [1], hint: 'Đó có thể là dấu hiệu của hỏa hoạn.', explanation: 'Báo ngay cho người lớn để kịp thời xử lý đám cháy.'),
    Question(id: 't2_l3_q2', levelId: 't2_l3', type: QuestionType.multipleChoice, question: 'Những nơi nào dễ trơn trượt?', options: ['Sàn nhà mới lau', 'Giường', 'Nhà tắm ướt', 'Thảm lông'], correctAnswers: [0, 2], hint: 'Nơi nào có nước thường dễ trượt ngã.', explanation: 'Sàn ướt hoặc nhà tắm rất trơn, cần đi cẩn thận.'),
    Question(id: 't2_l3_q3', levelId: 't2_l3', type: QuestionType.dialogue, question: 'Con xử lý ra sao?', options: ['Dùng tay nhặt mảnh vỡ', 'Đứng yên và gọi người lớn'], correctAnswers: [1], hint: 'Mảnh thủy tinh rất sắc.', explanation: 'Thủy tinh vỡ dễ làm đứt tay, hãy để người lớn dọn dẹp.', characterDialogue: 'Con làm vỡ một cái cốc thủy tinh.'),
    Question(id: 't2_l4_q1', levelId: 't2_l4', type: QuestionType.singleChoice, question: 'Khi ở nhà, nếu thấy cửa sổ mở to và gió mạnh, con nên làm gì?', options: ['Mở cửa ra chơi', 'Gọi người lớn để đóng lại', 'Đứng ngắm gió'], correctAnswers: [1], hint: 'Gió mạnh có thể làm cửa sổ bật tung.', explanation: 'Cửa sổ mở rộng dễ gây tai nạn; cần nhờ người lớn đóng lại.'),
    Question(id: 't2_l4_q2', levelId: 't2_l4', type: QuestionType.multipleChoice, question: 'Những hành vi nào dễ gây nguy hiểm ở tầng lầu?', options: ['Ngồi ở lan can', 'Đứng đợi người lớn', 'Đẩy bạn ra ngoài', 'Ngắm cảnh từ cửa sổ'], correctAnswers: [0, 2, 3], hint: 'Vùng cao dễ ngã.', explanation: 'Tuyệt đối không ngồi lan can, không đẩy bạn và không đứng gần mép cửa sổ.'),
    Question(id: 't2_l4_q3', levelId: 't2_l4', type: QuestionType.dialogue, question: 'Con nên làm gì khi bạn muốn trèo lên ghế để lấy đồ?', options: ['Cùng trèo để lấy đồ', 'Nói bạn dừng lại và nhờ người lớn'], correctAnswers: [1], hint: 'Ghế dễ trượt và ngã.', explanation: 'Không trèo lên ghế để lấy đồ vì dễ ngã và chấn thương.', characterDialogue: 'Bạn muốn trèo lên ghế để lấy một cái hộp ở trên cao.'),
    Question(id: 't2_l5_q1', levelId: 't2_l5', type: QuestionType.singleChoice, question: 'Dùng đồ ăn thừa hoặc thuốc trong nhà có nên uống bừa không?', options: ['Có', 'Không'], correctAnswers: [1], hint: 'Thuốc và thức ăn lạ có thể có hại.', explanation: 'Chỉ uống thuốc theo chỉ định của người lớn và không uống thức ăn lạ.'),
    Question(id: 't2_l5_q2', levelId: 't2_l5', type: QuestionType.multipleChoice, question: 'Hành động nào không an toàn khi ở nhà?', options: ['Giữ đồ ăn trong hũ kín', 'Để thuốc trong túi đồ chơi', 'Đậy nắp bình nước cẩn thận', 'Rửa tay trước khi ăn'], correctAnswers: [1], hint: 'Thuốc và đồ ăn không được đặt lẫn với đồ chơi.', explanation: 'Không để thuốc trong túi đồ chơi vì trẻ em dễ nhầm lẫn.'),
    Question(id: 't2_l5_q3', levelId: 't2_l5', type: QuestionType.dialogue, question: 'Con sẽ nói chuyện với em bé như thế nào?', options: ['Đừng ăn thuốc dù có vẻ ngọt', 'Để em ăn hết thuốc'], correctAnswers: [0], hint: 'Thuốc có thể làm em bị ngộ độc.', explanation: 'Thuốc không phải đồ ăn, phải để người lớn giữ và cho đúng cách.', characterDialogue: 'Em bé nói: "Con ăn viên thuốc ngọt như kẹo".'),
    Question(id: 't2_l6_q1', levelId: 't2_l6', type: QuestionType.singleChoice, question: 'Nếu thấy bếp đang nấu, con nên làm gì?', options: ['Ra chỗ nấu xem', 'Tránh xa và báo người lớn', 'Chạm tay vào nồi nóng'], correctAnswers: [1], hint: 'Bếp nóng có thể làm bỏng.', explanation: 'Phải ở xa bếp và nhờ người lớn chăm sóc khi nấu ăn.'),
    Question(id: 't2_l6_q2', levelId: 't2_l6', type: QuestionType.multipleChoice, question: 'Những vật nào có thể gây bỏng trong nhà?', options: ['Nồi nóng', 'Bát sứ', 'Chén nước ấm', 'Bàn là'], correctAnswers: [0, 3], hint: 'Những thứ tạo nhiệt cao.', explanation: 'Nồi nóng và bàn là có thể gây bỏng nếu chạm vào.'),
    Question(id: 't2_l6_q3', levelId: 't2_l6', type: QuestionType.dialogue, question: 'Con xử lý thế nào nếu đồ uống nóng đổ lên quần?', options: ['Cứ đứng yên', 'Lấy quần ra và gọi người lớn', 'Cào cào rồi chạm tiếp'], correctAnswers: [1], hint: 'Nước nóng làm bỏng da rất nhanh.', explanation: 'Đừng chạm vào vùng bị nóng, hãy báo người lớn để xử lý đúng.'),
    Question(id: 't2_l7_q1', levelId: 't2_l7', type: QuestionType.singleChoice, question: 'Khi thấy nhà tắm ướt, con nên làm gì?', options: ['Chạy nhảy', 'Đứng cẩn thận và kêu người lớn', 'Ngồi xuống'], correctAnswers: [1], hint: 'Sàn ướt dễ trượt.', explanation: 'Nhà tắm ướt dễ trượt ngã, nên cẩn thận và báo người lớn nếu cần.'),
    Question(id: 't2_l7_q2', levelId: 't2_l7', type: QuestionType.multipleChoice, question: 'Những việc nào giúp phòng tắm an toàn?', options: ['Để thảm chống trượt', 'Phơi quần áo ướt trên sàn', 'Mở vòi nước mạnh', 'Để khăn khô cạnh bồn'], correctAnswers: [0, 3], hint: 'Giữ phòng tắm khô và an toàn.', explanation: 'Thảm chống trượt và khăn khô ở gần bồn giúp giảm nguy cơ ngã.'),
    Question(id: 't2_l7_q3', levelId: 't2_l7', type: QuestionType.dialogue, question: 'Con nên làm gì khi thấy nước đọng quanh bồn rửa?', options: ['Đứng ở đó chờ', 'Nói người lớn lau khô lại', 'Là xuống bằng chân đi qua'], correctAnswers: [1], hint: 'Nước đọng rất trơn.', explanation: 'Nên báo người lớn lau khô để phòng trượt ngã.'),
    Question(id: 't2_l8_q1', levelId: 't2_l8', type: QuestionType.singleChoice, question: 'Điều gì nên làm trước khi mở tủ quần áo cao?', options: ['Nhảy lên ngay', 'Dùng ghế an toàn và hỏi người lớn', 'Để đồ rơi xuống'], correctAnswers: [1], hint: 'Tủ cao dễ có đồ rơi xuống.', explanation: 'Nên nhờ người lớn hoặc dùng ghế an toàn để tránh ngã.'),
    Question(id: 't2_l8_q2', levelId: 't2_l8', type: QuestionType.multipleChoice, question: 'Khi ở phòng ngủ, con nên tránh?', options: ['Trang trí gối', 'Chui dưới giường', 'Ngồi trên mép giường', 'Chơi với dây điện'], correctAnswers: [1, 2, 3], hint: 'Những nơi và thứ này dễ nguy hiểm.', explanation: 'Chui dưới giường, ngồi mép giường và dây điện đều có nguy cơ tai nạn.'),
    Question(id: 't2_l8_q3', levelId: 't2_l8', type: QuestionType.dialogue, question: 'Con sẽ nhắc ai?', options: ['Ai đó dùm mang đồ', 'Người lớn để cất đồ an toàn'], correctAnswers: [1], hint: 'Khẩn trương báo cho người lớn.', explanation: 'Để đồ an toàn, không để góc bàn và đèn điện có thể gây va chạm.', characterDialogue: 'Con thấy một hộp đồ chơi đè lên dây điện ở sàn phòng ngủ.'),
    Question(id: 't2_l9_q1', levelId: 't2_l9', type: QuestionType.singleChoice, question: 'Nếu thấy đồ chơi nhỏ nhỏ và có thể nuốt được, con nên làm gì?', options: ['Để cạnh mình', 'Cất đi và nhờ người lớn', 'Cho vào miệng'], correctAnswers: [1], hint: 'Đồ nhỏ có thể gây nghẹt thở.', explanation: 'Đồ chơi nhỏ phải được cất an toàn, không cho vào miệng.'),
    Question(id: 't2_l9_q2', levelId: 't2_l9', type: QuestionType.multipleChoice, question: 'Những loại đồ chơi nào cần cất ở chỗ cao?', options: ['Búp bê nhỏ', 'Xe đồ chơi lớn', 'Hạt nhựa nhỏ', 'Bảng chữ cái lớn'], correctAnswers: [0, 2], hint: 'Những thứ dễ nuốt không nên ở nơi dễ lấy.', explanation: 'Đồ nhỏ như hạt, nút, xe mini dễ gây nguy hiểm nếu nuốt phải.'),
    Question(id: 't2_l9_q3', levelId: 't2_l9', type: QuestionType.dialogue, question: 'Con nên làm gì khi em bé nhặt thứ gì đó ở sàn?', options: ['Cho em bé ăn', 'Nhắc em bé để xuống và báo người lớn'], correctAnswers: [1], hint: 'Có thể là vật nhỏ nguy hiểm.', explanation: 'Em bé cần được nhắc không nuốt đồ nhỏ và nhờ người lớn kiểm tra.'),
    Question(id: 't2_l10_q1', levelId: 't2_l10', type: QuestionType.singleChoice, question: 'Một ngôi nhà an toàn cần có điều gì?', options: ['Nhiều đồ vật treo lơ lửng', 'Vùng an toàn rõ ràng và người lớn đều biết', 'Đèn tắt tối'], correctAnswers: [1], hint: 'Nhà an toàn là nơi có người lớn và quy tắc rõ ràng.', explanation: 'Một căn nhà an toàn có quy tắc rõ và người lớn giám sát.'),
    Question(id: 't2_l10_q2', levelId: 't2_l10', type: QuestionType.multipleChoice, question: 'Những việc nào giúp giữ an toàn trong nhà?', options: ['Cất thuốc và vật sắc nhọn', 'Để đồ chơi nhỏ dưới gối', 'Dọn nước đọng', 'Nhắc bạn không trèo ghế'], correctAnswers: [0, 2, 3], hint: 'Hãy loại bỏ nguy cơ.', explanation: 'Cất thuốc, dọn nước đọng, nhắc nhở bạn không trèo ghế rất quan trọng.'),
    Question(id: 't2_l10_q3', levelId: 't2_l10', type: QuestionType.dialogue, question: 'Con sẽ nói gì khi thấy bạn làm nguy hiểm ở nhà?', options: ['Đừng làm thế nữa, hãy an toàn hơn', 'Cứ làm nếu thích'], correctAnswers: [0], hint: 'Bạn cần giúp đỡ.', explanation: 'Nói nhắc bạn dừng hành vi nguy hiểm là cách bảo vệ cả hai.'),
    Question(id: 't3_l1_q1', levelId: 't3_l1', type: QuestionType.singleChoice, question: 'Khi đi bơi, con cần có ai đi cùng?', options: ['Đi một mình', 'Người lớn', 'Bạn nhỏ bằng tuổi'], correctAnswers: [1], hint: 'Nước sâu rất nguy hiểm, cần người biết bơi bảo vệ.', explanation: 'Luôn cần người lớn giám sát khi đi bơi.'),
    Question(id: 't3_l1_q2', levelId: 't3_l1', type: QuestionType.multipleChoice, question: 'Những vật dụng bảo vệ khi đi nắng?', options: ['Áo mưa', 'Mũ rộng vành', 'Kính râm', 'Chăn bông'], correctAnswers: [1, 2], hint: 'Tránh bị say nắng và chói mắt.', explanation: 'Mũ và kính giúp bảo vệ con khỏi tia nắng gắt.'),
    Question(id: 't3_l1_q3', levelId: 't3_l1', type: QuestionType.dialogue, question: 'Con làm gì?', options: ['Chơi tiếp', 'Tìm nơi trú ẩn an toàn'], correctAnswers: [1], hint: 'Sấm sét rất nguy hiểm.', explanation: 'Sấm sét ở ngoài trời trống rất dễ đánh trúng người.', characterDialogue: 'Đang chơi ở công viên thì trời sấm chớp, sắp mưa to.'),
    Question(id: 't3_l2_q1', levelId: 't3_l2', type: QuestionType.singleChoice, question: 'Có nên trêu chọc chó mèo lạ ngoài đường không?', options: ['Có', 'Không bao giờ'], correctAnswers: [1], hint: 'Động vật lạ có thể hung dữ.', explanation: 'Chó mèo lạ có thể cắn hoặc cào gây bệnh dại.'),
    Question(id: 't3_l2_q2', levelId: 't3_l2', type: QuestionType.multipleChoice, question: 'Khi chơi xích đu, con không nên làm gì?', options: ['Ngồi vững', 'Đứng trên xích đu', 'Đi ngang qua xích đu đang đung đưa', 'Bám chặt tay'], correctAnswers: [1, 2], hint: 'Cần giữ thăng bằng và tránh va chạm.', explanation: 'Đứng trên xích đu dễ ngã, đi ngang qua dễ bị đập trúng.'),
    Question(id: 't3_l2_q3', levelId: 't3_l2', type: QuestionType.dialogue, question: 'Con làm sao?', options: ['Đồng ý', 'Từ chối vì rất nguy hiểm'], correctAnswers: [1], hint: 'Công trường có nhiều vật liệu rơi rớt.', explanation: 'Tuyệt đối không chơi gần công trường vì gạch đá có thể rơi trúng.', characterDialogue: 'Bạn rủ con ra chơi ở gần công trường đang xây dựng.'),
    Question(id: 't3_l3_q1', levelId: 't3_l3', type: QuestionType.singleChoice, question: 'Nếu đi lạc ở siêu thị, con nên làm gì đầu tiên?', options: ['Chạy lung tung khóc', 'Đứng yên tại chỗ và nhờ cô chú nhân viên', 'Ra khỏi siêu thị'], correctAnswers: [1], hint: 'Đứng yên sẽ giúp bố mẹ dễ tìm hơn.', explanation: 'Nhờ nhân viên mặc đồng phục gọi loa tìm bố mẹ.'),
    Question(id: 't3_l3_q2', levelId: 't3_l3', type: QuestionType.multipleChoice, question: 'Khi đi dã ngoại trong rừng, con cần chuẩn bị gì?', options: ['Nước uống', 'Thuốc xịt muỗi', 'Máy chơi game', 'Giày đi bộ'], correctAnswers: [0, 1, 3], hint: 'Chuẩn bị đồ dùng bảo vệ sức khỏe.', explanation: 'Nước, thuốc chống côn trùng và giày phù hợp rất cần thiết.'),
    Question(id: 't3_l3_q3', levelId: 't3_l3', type: QuestionType.dialogue, question: 'Phản ứng của con?', options: ['Lên xe luôn', 'Chạy đi và hét to nhờ giúp đỡ'], correctAnswers: [1], hint: 'Người lạ có thể có ý đồ xấu.', explanation: 'Không bao giờ lên xe người lạ.', characterDialogue: 'Có người không quen rủ con lên xe cho đi nhờ về nhà.'),
    Question(id: 't3_l4_q1', levelId: 't3_l4', type: QuestionType.singleChoice, question: 'Khi ở sân chơi, nếu thấy cầu trượt bị ướt, con nên làm gì?', options: ['Chơi tiếp', 'Nhảy lên ngay', 'Cẩn trọng và chờ khô hoặc nhờ người lớn'], correctAnswers: [2], hint: 'Cầu trượt ướt rất trơn.', explanation: 'Cầu trượt ướt dễ trượt ngã, nên chờ khô hoặc nhờ người lớn.'),
    Question(id: 't3_l4_q2', levelId: 't3_l4', type: QuestionType.multipleChoice, question: 'Những dụng cụ nào nên mặc khi đi chơi ngoài trời?', options: ['Mũ bảo hiểm', 'Áo khoác', 'Kính râm', 'Găng tay nặng'], correctAnswers: [0, 1, 2], hint: 'Bảo vệ cơ thể khỏi nắng và va chạm.', explanation: 'Mũ, áo khoác và kính râm giúp con an toàn hơn khi chơi ngoài trời.'),
    Question(id: 't3_l4_q3', levelId: 't3_l4', type: QuestionType.dialogue, question: 'Con sẽ lựa chọn gì?', options: ['Ngồi trên thanh chắn', 'Chơi ở khu vực an toàn và được giám sát'], correctAnswers: [1], hint: 'Một nơi an toàn có người lớn giám sát.', explanation: 'Nên chơi ở khu vực được giám sát để tránh va chạm và ngã.'),
    Question(id: 't3_l5_q1', levelId: 't3_l5', type: QuestionType.singleChoice, question: 'Khi đi bộ trên đường có nhiều xe, con nên đi ở đâu?', options: ['Giữa đường', 'Vỉa hè hoặc vạch đi bộ', 'Bên mép bờ cỏ'], correctAnswers: [1], hint: 'Có khu vực dành riêng cho người đi bộ.', explanation: 'Đi trên vỉa hè hoặc vạch đi bộ giúp con an toàn hơn.'),
    Question(id: 't3_l5_q2', levelId: 't3_l5', type: QuestionType.multipleChoice, question: 'Những việc nào nên làm khi đi ngang qua ngã tư?', options: ['Quan sát trái phải', 'Nhìn điện thoại', 'Chờ đèn đúng', 'Chạy vội'], correctAnswers: [0, 2], hint: 'Là người đi bộ, phải tuân thủ tín hiệu.', explanation: 'Nên quan sát kỹ và chờ tín hiệu đúng trước khi đi qua.'),
    Question(id: 't3_l5_q3', levelId: 't3_l5', type: QuestionType.dialogue, question: 'Con sẽ trả lời ai thế nào?', options: ['Đi cùng người lớn, không chạy bừa', 'Lập tức nhảy lên đường'], correctAnswers: [0], hint: 'Đi cùng người lớn sẽ an toàn hơn.', explanation: 'Nhất định không chạy bừa trên đường, phải đi cùng người lớn.'),
    Question(id: 't3_l6_q1', levelId: 't3_l6', type: QuestionType.singleChoice, question: 'Khi trời nắng gắt, con nên làm gì?', options: ['Ngồi dưới gốc cây hoặc nơi mát', 'Chạy ra bãi cỏ bằng phẳng', 'Ngủ dưới trời'], correctAnswers: [0], hint: 'Hãy tránh nắng trực tiếp.', explanation: 'Nắng gắt có thể gây say nắng, nên tìm nơi mát và uống nước.'),
    Question(id: 't3_l6_q2', levelId: 't3_l6', type: QuestionType.multipleChoice, question: 'Những vật nào giúp bảo vệ khỏi mưa nắng?', options: ['Mũ', 'Kính râm', 'Áo khoác mỏng', 'Nước uống'], correctAnswers: [0, 1, 3], hint: 'Bảo vệ thân thể và giữ nước.', explanation: 'Mũ, kính râm và nước uống giúp con an toàn hơn dưới trời nắng.'),
    Question(id: 't3_l6_q3', levelId: 't3_l6', type: QuestionType.dialogue, question: 'Con nên làm gì khi thấy sấm chớp?', options: ['Chạy ra bãi trống', 'Tìm nơi trú ẩn và báo người lớn'], correctAnswers: [1], hint: 'Trống không dễ bị sét đánh.', explanation: 'Hãy tìm nơi chắn và báo người lớn để tránh sét đánh.'),
    Question(id: 't3_l7_q1', levelId: 't3_l7', type: QuestionType.singleChoice, question: 'Nếu bị lạc ở công viên, con nên làm gì?', options: ['Đi loanh quanh', 'Ở yên và tìm người lớn hoặc nhân viên', 'Vào quán nước'], correctAnswers: [1], hint: 'Đừng đi lang thang khi lạc.', explanation: 'Ở lại ở chỗ an toàn và nhờ người lớn hoặc nhân viên hỗ trợ.'),
    Question(id: 't3_l7_q2', levelId: 't3_l7', type: QuestionType.multipleChoice, question: 'Những nơi nào là chỗ an toàn khi bị lạc?', options: ['Trụ cứu hộ', 'Cổng công viên', 'Gần bồn nước', 'Khu vực có nhiều người'], correctAnswers: [0, 1, 3], hint: 'Những nơi dễ tìm người giúp đỡ.', explanation: 'Trụ cứu hộ, cổng công viên và nơi đông người là chỗ tốt để chờ giúp đỡ.'),
    Question(id: 't3_l7_q3', levelId: 't3_l7', type: QuestionType.dialogue, question: 'Con nói gì với nhân viên?', options: ['Con bị lạc, cần tìm bố mẹ', 'Con đi một mình được'], correctAnswers: [0], hint: 'Nhân viên có thể giúp tìm người thân.', explanation: 'Nói rõ tình trạng để nhân viên hỗ trợ đúng cách.'),
    Question(id: 't3_l8_q1', levelId: 't3_l8', type: QuestionType.singleChoice, question: 'Nếu thấy một con chó lạ, con nên làm gì?', options: ['Chạy tới chạm', 'Ngồi xuống và để người lớn xử lý', 'Bước lên phía trước'], correctAnswers: [1], hint: 'Động vật lạ có thể bất ngờ.', explanation: 'Đừng chạm vào động vật lạ, để người lớn xử lý.'),
    Question(id: 't3_l8_q2', levelId: 't3_l8', type: QuestionType.multipleChoice, question: 'Những hành vi nào nên tránh khi ở công viên?', options: ['Đứng gần cổng', 'Treo người trên hàng rào', 'Chơi đúng sân', 'Đứng gần hồ nước'], correctAnswers: [1, 3], hint: 'Những chỗ dễ mất thăng bằng hoặc ngộp nước.', explanation: 'Không trèo hàng rào và không đứng quá gần hồ nước.'),
    Question(id: 't3_l8_q3', levelId: 't3_l8', type: QuestionType.dialogue, question: 'Con nên làm gì nếu bị chó đuổi?', options: ['Chạy thẳng tới', 'Giữ bình tĩnh và đi về phía người lớn'], correctAnswers: [1], hint: 'Chó dễ bám theo người chạy.', explanation: 'Luôn giữ bình tĩnh và tìm người lớn, không chạy thẳng vào nó.'),
    Question(id: 't3_l9_q1', levelId: 't3_l9', type: QuestionType.singleChoice, question: 'Nếu đi đường gồ ghề, con nên?', options: ['Nhảy qua nhanh', 'Đi chậm và quan sát', 'Cúi đầu đi'], correctAnswers: [1], hint: 'An toàn hơn trong mọi địa hình.', explanation: 'Đi chậm và quan sát giúp con không ngã hoặc trượt.'),
    Question(id: 't3_l9_q2', levelId: 't3_l9', type: QuestionType.multipleChoice, question: 'Những nơi nào dễ bị ngã?', options: ['Đường bằng phẳng', 'Đường gồ ghề', 'Bậc thềm ướt', 'Sân cỏ khô'], correctAnswers: [1, 2], hint: 'Bề mặt không bằng phẳng có nguy cơ trượt.', explanation: 'Đường gồ ghề và bậc thềm ướt dễ gây ngã.'),
    Question(id: 't3_l9_q3', levelId: 't3_l9', type: QuestionType.dialogue, question: 'Con nên nhắc bạn như thế nào?', options: ['Đi chậm và cẩn thận', 'Đẩy nhau chơi cho vui'], correctAnswers: [0], hint: 'Không đẩy nhau ở nơi có thể ngã.', explanation: 'Đi chậm và quan sát là cách an toàn nhất.'),
    Question(id: 't3_l10_q1', levelId: 't3_l10', type: QuestionType.singleChoice, question: 'Một chuyến đi ngoài trời an toàn bắt đầu từ đâu?', options: ['Từ việc nhờ người lớn đi cùng', 'Từ việc chạy nhảy trước', 'Từ việc ở một mình'], correctAnswers: [0], hint: 'Người lớn là người giám sát.', explanation: 'Đi cùng người lớn và biết các quy tắc giúp con an toàn hơn.'),
    Question(id: 't3_l10_q2', levelId: 't3_l10', type: QuestionType.multipleChoice, question: 'Bài học nào giúp con an toàn khi ra ngoài?', options: ['Tìm người lớn khi lạc', 'Không chạm động vật lạ', 'Chạy thật nhanh', 'Chờ tín hiệu an toàn'], correctAnswers: [0, 1, 3], hint: 'An toàn là nhờ thận trọng.', explanation: 'Không chạy bừa, không chạm động vật lạ và luôn tìm người lớn khi cần hỗ trợ.'),
    Question(id: 't3_l10_q3', levelId: 't3_l10', type: QuestionType.dialogue, question: 'Con sẽ nói gì nếu bạn muốn thử hành động nguy hiểm ở ngoài trời?', options: ['Đừng làm thế, nguy hiểm lắm', 'Cứ thử một lần thôi'], correctAnswers: [0], hint: 'Nguy hiểm không đáng thử.', explanation: 'Hãy nhắc bạn dừng lại vì an toàn quan trọng hơn mọi thứ.'),
    Question(id: 't4_l1_q1', levelId: 't4_l1', type: QuestionType.singleChoice, question: 'Khi người lạ cho kẹo, con có nên nhận không?', options: ['Nhận và ăn ngay', 'Không nhận và từ chối lịch sự'], correctAnswers: [1], hint: 'Đồ ăn từ người lạ có thể có thuốc mê.', explanation: 'Chỉ nhận đồ ăn khi có sự cho phép của bố mẹ.'),
    Question(id: 't4_l1_q2', levelId: 't4_l1', type: QuestionType.multipleChoice, question: 'Người lớn đáng tin cậy là ai?', options: ['Bố mẹ', 'Người mới gặp ở công viên', 'Thầy cô giáo', 'Chú công an'], correctAnswers: [0, 2, 3], hint: 'Những người chăm sóc hoặc bảo vệ con.', explanation: 'Bố mẹ, thầy cô, chú công an là người có thể giúp đỡ con an toàn.'),
    Question(id: 't4_l1_q3', levelId: 't4_l1', type: QuestionType.dialogue, question: 'Con làm gì?', options: ['Vào chơi', 'Không vào và đợi bố mẹ về'], correctAnswers: [1], hint: 'Không vào nhà người khác khi không có bố mẹ đi cùng.', explanation: 'Cần giữ an toàn, không vào nhà người khác một mình.', characterDialogue: 'Chú hàng xóm rủ con vào nhà chú chơi lúc bố mẹ đi vắng.'),
    Question(id: 't4_l2_q1', levelId: 't4_l2', type: QuestionType.singleChoice, question: 'Có người lạ gõ cửa khi con ở nhà một mình, con làm gì?', options: ['Mở cửa ngay', 'Không mở cửa và im lặng'], correctAnswers: [1], hint: 'Người lạ có thể làm hại con.', explanation: 'Không bao giờ mở cửa cho người lạ khi ở nhà một mình.'),
    Question(id: 't4_l2_q2', levelId: 't4_l2', type: QuestionType.multipleChoice, question: 'Những thông tin KHÔNG nên nói cho người lạ?', options: ['Tên trường học', 'Màu sắc yêu thích', 'Địa chỉ nhà', 'Mật khẩu điện thoại'], correctAnswers: [0, 2, 3], hint: 'Những thông tin cá nhân quan trọng.', explanation: 'Tuyệt đối giữ bí mật địa chỉ, trường học để tránh bị kẻ xấu tìm đến.'),
    Question(id: 't4_l2_q3', levelId: 't4_l2', type: QuestionType.dialogue, question: 'Con phản ứng ra sao?', options: ['Đi theo', 'Vùng vẫy, hét to "Cứu cháu với!"'], correctAnswers: [1], hint: 'Phải gây chú ý để người xung quanh giúp đỡ.', explanation: 'Hét thật to và giãy giụa để thoát thân.', characterDialogue: 'Người lạ cố tình nắm tay và kéo con đi.'),
    Question(id: 't4_l3_q1', levelId: 't4_l3', type: QuestionType.singleChoice, question: 'Quy tắc 5 ngón tay giúp con bảo vệ bản thân khỏi điều gì?', options: ['Bị ốm', 'Bị xâm hại', 'Bị điểm kém'], correctAnswers: [1], hint: 'Quy tắc về khoảng cách giao tiếp.', explanation: 'Quy tắc 5 ngón tay giúp xác định khoảng cách an toàn với người khác.'),
    Question(id: 't4_l3_q2', levelId: 't4_l3', type: QuestionType.multipleChoice, question: 'Những vùng nhạy cảm trên cơ thể (vùng đồ bơi) mà người khác KHÔNG được chạm vào?', options: ['Tóc', 'Ngực', 'Giữa hai đùi', 'Mông'], correctAnswers: [1, 2, 3], hint: 'Những nơi được che bởi đồ bơi.', explanation: 'Đó là vùng kín, tuyệt đối không ai được chạm vào trừ bác sĩ khi khám bệnh có mẹ ở đó.'),
    Question(id: 't4_l3_q3', levelId: 't4_l3', type: QuestionType.dialogue, question: 'Con làm sao?', options: ['Giữ bí mật', 'Kể ngay cho bố mẹ'], correctAnswers: [1], hint: 'Những bí mật khiến con lo sợ thì phải nói ra.', explanation: 'Kẻ xấu thường ép trẻ em giữ bí mật. Phải nói ngay cho người tin cậy.', characterDialogue: 'Một người ép con giữ bí mật về việc họ chạm vào vùng nhạy cảm của con.'),
    Question(id: 't4_l4_q1', levelId: 't4_l4', type: QuestionType.singleChoice, question: 'Nếu người lạ hỏi tên và địa chỉ, con nên đáp?', options: ['Nói đầy đủ', 'Chỉ nói tên mình và hỏi lại', 'Không nói và tìm bố mẹ'], correctAnswers: [2], hint: 'Chỉ nói những thông tin cần thiết sau khi được người lớn cho phép.', explanation: 'Không tiết lộ địa chỉ và thông tin cá nhân khi chưa có người lớn cho phép.'),
    Question(id: 't4_l4_q2', levelId: 't4_l4', type: QuestionType.multipleChoice, question: 'Những việc nào nên làm khi bị người lạ hỏi quá nhiều?', options: ['Lùi lại', 'Gọi bố mẹ', 'Pha trò rồi đi', 'Bỏ chạy về nơi đông người'], correctAnswers: [0, 1, 3], hint: 'Nên tách khỏi người lạ và tìm người lớn.', explanation: 'Lùi lại, gọi bố mẹ hoặc chạy về nơi đông người là cách an toàn.'),
    Question(id: 't4_l4_q3', levelId: 't4_l4', type: QuestionType.dialogue, question: 'Con nên nói gì?', options: ['Đừng rời khỏi nơi này', 'Bố mẹ đang ở đó, cháu muốn gặp bố mẹ'], correctAnswers: [1], hint: 'Con cần nói rõ mình đang tìm người lớn.', explanation: 'Nói rõ mình cần bố mẹ là cách nhắn tới người lớn xung quanh.'),
    Question(id: 't4_l5_q1', levelId: 't4_l5', type: QuestionType.singleChoice, question: 'Khi đi học, nếu ai đó gọi con ra khỏi lớp mà không có bố mẹ, con nên?', options: ['Đi theo ngay', 'Báo thầy cô', 'Chạy đằng sau'], correctAnswers: [1], hint: 'Thầy cô là người lớn đáng tin cậy.', explanation: 'Không đi theo người lạ, hãy báo thầy cô hoặc người lớn trong trường.'),
    Question(id: 't4_l5_q2', levelId: 't4_l5', type: QuestionType.multipleChoice, question: 'Phương án nào an toàn khi đến trường?', options: ['Đi cùng bố mẹ', 'Đợi ở cổng', 'Đi cùng bạn biết rõ', 'Đi theo người lạ'], correctAnswers: [0, 2], hint: 'Chỉ đi với người đã quen biết.', explanation: 'Đi cùng bố mẹ hoặc bạn thân được gia đình đồng ý là an toàn nhất.'),
    Question(id: 't4_l5_q3', levelId: 't4_l5', type: QuestionType.dialogue, question: 'Con sẽ làm gì trước khi đi với ai đó?', options: ['Hỏi người lớn cho phép trước', 'Em chạy đi ngay'], correctAnswers: [0], hint: 'Không ai có thể thu hút con đi mà không sự cho phép.', explanation: 'Luôn hỏi ý kiến bố mẹ hoặc người lớn đáng tin cậy trước khi đi với ai.'),
    Question(id: 't4_l6_q1', levelId: 't4_l6', type: QuestionType.singleChoice, question: 'Nếu có người nói “đừng kể với ai, đó là bí mật” nên làm gì?', options: ['Tin lời và giữ kín', 'Kể cho bố mẹ hoặc thầy cô', 'Cười rồi im lặng'], correctAnswers: [1], hint: 'Không ai nên bắt con giữ bí mật về việc xấu.', explanation: 'Con cần kể cho người lớn đáng tin cậy nếu cảm thấy không an toàn.'),
    Question(id: 't4_l6_q2', levelId: 't4_l6', type: QuestionType.multipleChoice, question: 'Những người nào con nên kể khi bị đe dọa?', options: ['Bố mẹ', 'Chú công an', 'Người lạ trên đường', 'Thầy cô'], correctAnswers: [0, 1, 3], hint: 'Chỉ kể với người đáng tin cậy.', explanation: 'Bố mẹ, thầy cô và chú công an là người có thể giúp con.'),
    Question(id: 't4_l6_q3', levelId: 't4_l6', type: QuestionType.dialogue, question: 'Con sẽ nói gì?', options: ['Cháu sợ, cháu muốn nói cho bố mẹ', 'Cháu không muốn ai biết'], correctAnswers: [0], hint: 'Con không cần giữ bí mật với tình huống nguy hiểm.', explanation: 'Nói cho người lớn biết là hành động đúng đắn để được bảo vệ.'),
    Question(id: 't4_l7_q1', levelId: 't4_l7', type: QuestionType.singleChoice, question: 'Nếu người lạ mời con đi ăn hoặc mua đồ, con nên?', options: ['Nhận lời ngay', 'Từ chối lịch sự và quay về tìm bố mẹ', 'Đợi họ đưa về nhà'], correctAnswers: [1], hint: 'Không nên đi cùng người không quen.', explanation: 'Từ chối lịch sự rồi quay về nơi bố mẹ hoặc người lớn đang chờ.'),
    Question(id: 't4_l7_q2', levelId: 't4_l7', type: QuestionType.multipleChoice, question: 'Những câu nói nào là cảnh báo của người lạ?', options: ['"Con đi cùng mẹ đi nhé"', '"Bố mẹ đang ở xa, con theo tôi đi"', '"Con đừng kể với ai"', '"Con có muốn ăn kẹo không"'], correctAnswers: [1, 2, 3], hint: 'Đó là lời mời hoặc lời ép nguy hiểm.', explanation: 'Những lời lừa đảo hoặc ép con đi cùng đều nguy hiểm.'),
