  static List<Question> _withIllustrations(List<Question> baseQuestions) {
    return baseQuestions.map((question) {
      final promptText = question.correctAnswers.length > 1
          ? '${question.question.trim()} (Chọn ${question.correctAnswers.length})'
          : question.question.trim();

      final imagePath = 'assets/question_art/${question.id}.png';
      return question.copyWith(
        question: promptText,
        image: imagePath,
      );
    }).toList();
  }

