  static BadgeModel? getBadgeById(String badgeId) {
    try {
      return badges.firstWhere((b) => b.id == badgeId);
    } catch (_) {
      return null;
    }
  }

  static String getBadgeRequirementText(String badgeId) {
    try {
      final badge = badges.firstWhere((b) => b.id == badgeId);
      return badge.description;
    } catch (_) {
      return 'Hoàn thành các yêu cầu của thành tựu để mở khóa.';
    }
  }

